// Validity of a value read from shared memory (D6).  Only bool, and the enums and the
// records and arrays containing them, have invalid bit patterns; the rest are always
// valid.  A bool is read as a byte, since reading a bool object that holds neither 0 nor
// 1 is itself undefined.
static inline bool bool_is_valid(const bool *v) { return *(const uint8_t *) v <= 1; }
static inline bool char_is_valid(const char *v) { (void) v; return true; }
static inline bool int8_t_is_valid(const int8_t *v) { (void) v; return true; }
static inline bool int16_t_is_valid(const int16_t *v) { (void) v; return true; }
static inline bool int32_t_is_valid(const int32_t *v) { (void) v; return true; }
static inline bool int64_t_is_valid(const int64_t *v) { (void) v; return true; }
static inline bool uint8_t_is_valid(const uint8_t *v) { (void) v; return true; }
static inline bool uint16_t_is_valid(const uint16_t *v) { (void) v; return true; }
static inline bool uint32_t_is_valid(const uint32_t *v) { (void) v; return true; }
static inline bool uint64_t_is_valid(const uint64_t *v) { (void) v; return true; }
static inline bool float_is_valid(const float *v) { (void) v; return true; }
static inline bool double_is_valid(const double *v) { (void) v; return true; }

typedef
  enum {Idle, Active, Fault} Exhaustive_Monitor_OperatingState;

_Static_assert(sizeof(Exhaustive_Monitor_OperatingState) == 4, "Exhaustive_Monitor_OperatingState: memory layout differs from HAMR's");
_Static_assert(_Alignof(Exhaustive_Monitor_OperatingState) == 4, "Exhaustive_Monitor_OperatingState: memory layout differs from HAMR's");


static inline bool Exhaustive_Monitor_OperatingState_is_valid(const Exhaustive_Monitor_OperatingState *v) {
  return (uint32_t) *v < 3;
}

#define Exhaustive_Monitor_Samples_DIM_0 4

typedef int32_t Exhaustive_Monitor_Samples [Exhaustive_Monitor_Samples_DIM_0];

#define Exhaustive_Monitor_Samples_BYTE_SIZE (sizeof(Exhaustive_Monitor_Samples))

_Static_assert(sizeof(Exhaustive_Monitor_Samples) == 16, "Exhaustive_Monitor_Samples: memory layout differs from HAMR's");
_Static_assert(_Alignof(Exhaustive_Monitor_Samples) == 4, "Exhaustive_Monitor_Samples: memory layout differs from HAMR's");


static inline bool Exhaustive_Monitor_Samples_is_valid(const Exhaustive_Monitor_Samples *v) {
  for (size_t i = 0; i < Exhaustive_Monitor_Samples_DIM_0; i++) {
    if (!int32_t_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

typedef struct Exhaustive_Monitor_Telemetry_i {
  int32_t sequence_number;
  bool valid;
  Exhaustive_Monitor_Samples values;
  Exhaustive_Monitor_OperatingState operating_state;
} Exhaustive_Monitor_Telemetry_i;

_Static_assert(sizeof(Exhaustive_Monitor_Telemetry_i) == 28, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");
_Static_assert(_Alignof(Exhaustive_Monitor_Telemetry_i) == 4, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");
_Static_assert(offsetof(Exhaustive_Monitor_Telemetry_i, sequence_number) == 0, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");
_Static_assert(offsetof(Exhaustive_Monitor_Telemetry_i, valid) == 4, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");
_Static_assert(offsetof(Exhaustive_Monitor_Telemetry_i, values) == 8, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");
_Static_assert(offsetof(Exhaustive_Monitor_Telemetry_i, operating_state) == 24, "Exhaustive_Monitor_Telemetry_i: memory layout differs from HAMR's");

static inline bool Exhaustive_Monitor_Telemetry_i_is_valid(const Exhaustive_Monitor_Telemetry_i *v) {
  return int32_t_is_valid(&v->sequence_number) &&
                  bool_is_valid(&v->valid) &&
                  Exhaustive_Monitor_Samples_is_valid(&v->values) &&
                  Exhaustive_Monitor_OperatingState_is_valid(&v->operating_state);
}
